int a[MAXN], t[4 * MAXN];
int build(int k, int l, int r) {       // 노드 k가 a[l..r]을 맡는다
    if (l == r) return t[k] = a[l];
    int m = (l + r) / 2;
    return t[k] = build(2 * k, l, m) + build(2 * k + 1, m + 1, r);
}
// 호출: build(1, 0, n - 1)

